<?php defined('BASEPATH') or exit('No direct script access allowed');$r=$report;$s=$r['session'];function pm($v){return number_format((float)$v,0,'.',',');}?><!doctype html><html dir="rtl"><head><meta charset="utf-8"><title>گزارش تحویل صندوق</title><style>body{font-family:Tahoma,Arial;padding:30px;color:#222}h2{text-align:center}.meta,.sum{width:100%;border-collapse:collapse;margin:20px 0}.meta td,.sum th,.sum td{border:1px solid #bbb;padding:9px}.sign{margin-top:70px;display:flex;justify-content:space-between}.sign div{width:30%;text-align:center;border-top:1px solid #777;padding-top:10px}@media print{button{display:none}}</style></head><body><button onclick="window.print()">چاپ</button><h2>گزارش روزانه محاسبه و تحویل صندوق</h2><table class="meta"><tr><td>تاریخ: <?=html_escape($s['business_date'])?></td><td>صندوقدار: <?=html_escape($r['staff_name'])?></td><td>شماره گزارش: <?=$s['id']?></td></tr></table><table class="sum"><tr><th>روش پرداخت</th><th>دسته</th><th>تعداد</th><th>مبلغ</th></tr><?php foreach($r['modes'] as $m):?><tr><td><?=html_escape($m['label'])?> <?=html_escape($m['account_label'])?></td><td><?=_l('scr_payment_cat_'.$m['category'])?></td><td><?=$m['count']?></td><td><?=pm($m['amount'])?></td></tr><?php endforeach?><tr><th colspan="3">جمع دریافت‌ها</th><th><?=pm($r['totals']['all'])?></th></tr><tr><th colspan="3">وجه نقد مورد انتظار</th><th><?=pm($r['totals']['cash'])?></th></tr><tr><th colspan="3">وجه نقد اعلامی صندوقدار</th><th><?=pm($s['actual_cash'])?></th></tr><tr><th colspan="3">کسری / اضافه</th><th><?=pm($s['cash_difference'])?></th></tr></table><p><b>یادداشت صندوقدار:</b> <?=nl2br(html_escape($s['cashier_note']))?></p><p><b>یادداشت حسابدار:</b> <?=nl2br(html_escape($s['accountant_note']))?></p><?php if(!empty($s['discrepancy_type'])):?><p><b>مغایرت:</b> <?=html_escape(_l('scr_discrepancy_'.$s['discrepancy_type']))?> - <?=pm($s['discrepancy_amount'])?></p><?php endif;?><?php if(!empty($s['cashier_response'])):?><p><b>پاسخ صندوقدار:</b> <?=nl2br(html_escape($s['cashier_response']))?></p><?php endif;?><div class="sign"><div>نام و امضای صندوقدار</div><div>نام و امضای تحویل‌گیرنده</div><div>تاریخ و ساعت تحویل</div></div></body></html>
